package dev.minegame.mines;
import java.util.*;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
public final class FightsTabCompleter implements TabCompleter {
 private final FightsManager fights; public FightsTabCompleter(FightsManager fights){this.fights=fights;}
 public List<String> onTabComplete(CommandSender sender,Command command,String alias,String[] args){String name=command.getName().toLowerCase(Locale.ROOT);if(name.equals("fighter")){if(args.length==1){int n=sender instanceof Player p?fights.nearbyFighterCount(p):2;List<String> out=new ArrayList<>();for(int i=1;i<=n;i++)out.add(String.valueOf(i));return filter(args[0],out);}if(args.length==2)return filter(args[1],List.of("1","10","100","1000"));}if(name.equals("fightadmin")){if(args.length==1)return filter(args[0],List.of("create","fighters","move","remove","regen","list","holo","set"));if(args.length==2&&List.of("fighters","move","remove","regen","holo").contains(args[0].toLowerCase(Locale.ROOT)))return filter(args[1],numbers());if(args.length>=3&&args.length<=5&&args[0].equalsIgnoreCase("move"))return filter(args[args.length-1],List.of("-10","-1","0","1","10"));if(args.length==2&&args[0].equalsIgnoreCase("create"))return filter(args[1],List.of("5","7","9","11","13","15"));if(args.length==3&&args[0].equalsIgnoreCase("create"))return filter(args[2],fighterCounts());if(args.length==3&&args[0].equalsIgnoreCase("fighters"))return filter(args[2],fighterCounts());if(args.length==2&&args[0].equalsIgnoreCase("set"))return filter(args[1],settings());if(args.length==3&&args[0].equalsIgnoreCase("set")){if(args[1].contains("arena-style"))return filter(args[2],List.of("walls","fence"));if(args[1].contains("bet-display-mode"))return filter(args[2],List.of("below_fighter","bottom"));if(args[1].contains("mode"))return filter(args[2],List.of("always","betting_only"));if(args[1].contains("enabled"))return filter(args[2],List.of("true","false"));}if(args.length==3&&args[0].equalsIgnoreCase("holo"))return filter(args[2],List.of("reset"));}return List.of();}
 private List<String> settings(){return List.of("betting-seconds","celebration-seconds","min-bet","max-bet","payout-multiplier","activation-distance","hologram-height","hologram-line-spacing","hologram-view-range","show-bettor-name-on-fighter","hologram.bet-display-mode","max-fighters","fireworks-per-winner","arena-style","casino-frame-animation.enabled","casino-frame-animation.block","casino-frame-animation.mode","casino-frame-animation.pattern","blocks.fill-block","blocks.frame-block","blocks.fence-block","blocks.casino-frame-block");} private List<String> numbers(){List<String> n=new ArrayList<>();for(int i=1;i<=Math.max(1,fights.stations().size());i++)n.add(String.valueOf(i));return n;} private List<String> fighterCounts(){List<String> n=new ArrayList<>();for(int i=2;i<=16;i++)n.add(String.valueOf(i));return n;} private List<String> filter(String p,List<String> v){return v.stream().filter(x->x.startsWith(p)).toList();}
}